INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('877033f4-0313-41ec-a662-f27b93ac1a05', 'Muma''s bday ', 'muma-s-bday', '', 'You were super excited for Mumma''s birthday! From the moment you saw the cake, your eyes sparkled with joy. You couldn''t wait for the best part - cutting the cake with Mumma!

Holding Mumma''s hand, standing close to her, and cutting the cake together - that smile on your face said it all. It was your little way of making the day even more special.

Thank you for every hug, every smile and every bit of love. You are my first home, your forever safe place. ', '2026-03-09', '', 'toddler', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/muma-s-bday/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/muma-s-bday/gallery/877033f4-0313-41ec-a662-f27b93ac1a05-0.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/muma-s-bday/gallery/877033f4-0313-41ec-a662-f27b93ac1a05-1.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/muma-s-bday/gallery/877033f4-0313-41ec-a662-f27b93ac1a05-2.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/muma-s-bday/gallery/877033f4-0313-41ec-a662-f27b93ac1a05-3.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/muma-s-bday/gallery/877033f4-0313-41ec-a662-f27b93ac1a05-4.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/muma-s-bday/gallery/877033f4-0313-41ec-a662-f27b93ac1a05-5.webp"]', '[]', 0, 1, 'muma-s-bday', '2026-08-16T12:10:07.104176+00:00', '2026-08-21T13:00:11.939343+00:00', NULL, NULL, 'memory');
INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('5868468d-b147-4c00-b176-e2801d635c50', 'Photoshoot ', 'photoshoot', '', 'Some moments are planned, some happen completely at random — and somehow, those are often the most beautiful ones. ❤️

You’ve always been ready to click, turning even the most ordinary moment into a little photoshoot. Give you a camera and suddenly that curious little look, that adorable expression, or that perfectly timed pose appears out of nowhere. 📸✨

With your natural charm and those photogenic expressions, you never really need a pose. You simply be yourself, and somehow the camera always finds the magic.

Every look tells a different story. Every expression captures a little piece of your personality. And every random click becomes another memory we want to keep forever.

You are truly photogenic, camera-ready, and always ready for your next click! 💙

Because with you, we don’t need a reason for a photoshoot — you are the reason. 📸🥰', '2026-04-01', '', 'toddler', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/photoshoot/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/photoshoot/gallery/5868468d-b147-4c00-b176-e2801d635c50-0.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/photoshoot/gallery/5868468d-b147-4c00-b176-e2801d635c50-1.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/photoshoot/gallery/5868468d-b147-4c00-b176-e2801d635c50-2.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/photoshoot/gallery/5868468d-b147-4c00-b176-e2801d635c50-3.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/photoshoot/gallery/5868468d-b147-4c00-b176-e2801d635c50-4.webp","https://fbfdwmlqoxfcqhodldpw.supabase.co/storage/v1/object/public/timeline/photoshoot/gallery/1786881770110-ryy5lb33.jpg","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/photoshoot/gallery/5868468d-b147-4c00-b176-e2801d635c50-6.webp","https://fbfdwmlqoxfcqhodldpw.supabase.co/storage/v1/object/public/timeline/photoshoot/gallery/1786881770780-7k770232.jpg","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/photoshoot/gallery/5868468d-b147-4c00-b176-e2801d635c50-8.webp","https://fbfdwmlqoxfcqhodldpw.supabase.co/storage/v1/object/public/timeline/photoshoot/gallery/1786881771529-ry3i2hy7.jpg","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/photoshoot/gallery/5868468d-b147-4c00-b176-e2801d635c50-10.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/photoshoot/gallery/5868468d-b147-4c00-b176-e2801d635c50-11.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/photoshoot/gallery/5868468d-b147-4c00-b176-e2801d635c50-12.webp","https://azain-media-wo