INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('7d2e0961-ef22-4027-bf16-a543ea55a5bd', '4 Months of you...', '4-months-of-you', '', 'Four months ago, you were still so tiny in our arms.
Today, you already seem to have your own little personality, your own expressions, and your own way of filling every room with happiness.

Four months of tiny hands reaching out.
Four months of curious eyes discovering everything around you.
Four months of little smiles that can brighten even the most ordinary day.

And somewhere along the way, we realized that time is moving far too quickly.

Every photograph we take, every silly video we record, every little outfit we dress you in — we''re trying to hold on to these days for just a little longer.

Today, you''re lying here surrounded by little treats, with your tiny number 4 beside you, looking as though you already know that this is your special day.

But the truth is, we don''t need a reason to celebrate you.

Every day with you is a celebration.

Four months of watching you grow.
Four months of learning you.
Four months of loving you more than we knew was possible.

And this is only the beginning.

Happy 4 Months, our little adventurer. 🤍

Keep growing, keep discovering, keep surprising us.

We''ll keep capturing the little moments — because one day, these tiny days will be the memories we treasure most.', '2025-01-14', '', 'infant', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/4-months-of-you/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/4-months-of-you/gallery/7d2e0961-ef22-4027-bf16-a543ea55a5bd-0.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/4-months-of-you/gallery/7d2e0961-ef22-4027-bf16-a543ea55a5bd-1.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/4-months-of-you/gallery/7d2e0961-ef22-4027-bf16-a543ea55a5bd-2.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/4-months-of-you/gallery/7d2e0961-ef22-4027-bf16-a543ea55a5bd-3.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/4-months-of-you/gallery/7d2e0961-ef22-4027-bf16-a543ea55a5bd-4.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/4-months-of-you/gallery/7d2e0961-ef22-4027-bf16-a543ea55a5bd-5.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/4-months-of-you/gallery/7d2e0961-ef22-4027-bf16-a543ea55a5bd-6.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/4-months-of-you/gallery/7d2e0961-ef22-4027-bf16-a543ea55a5bd-7.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/4-months-of-you/gallery/7d2e0961-ef22-4027-bf16-a543ea55a5bd-8.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/4-months-of-you/gallery/7d2e0961-ef22-4027-bf16-a543ea55a5bd-9.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/4-months-of-you/gallery/7d2e0961-ef22-4027-bf16-a543ea55a5bd-10.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/4-months-of-you/gallery/7d2e0961-ef22-4027-bf16-a543ea55a5bd-11.webp"]', '[]', 0, 1, '4-mon