INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('5053efed-d137-4a84-8ce5-203b1e03b4c3', 'Beach Day..', 'beach-day', '', 'Beach Day — Little Legs, Big Adventure 🌊☀️

Some days are meant to be remembered forever, and this was one of them. With the sea stretching endlessly ahead, the sand beneath our feet, and you sitting proudly on Daddy’s shoulders, the world suddenly felt like the perfect place to be.

You were our tiniest beach explorer, taking in the waves, the breeze, the sounds, and everything around you from the best seat on the beach
We may forget the little details one day—the weather, the crowd, the exact time—but we will never forget the feeling of carrying you by the sea and watching your little adventure unfold.

Sun, sand, sea, and you—one beautiful day, one unforgettable memory. 💙🌴', '2025-06-04', '', 'infant', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day/gallery/5053efed-d137-4a84-8ce5-203b1e03b4c3-0.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day/gallery/5053efed-d137-4a84-8ce5-203b1e03b4c3-1.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day/gallery/5053efed-d137-4a84-8ce5-203b1e03b4c3-2.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day/gallery/5053efed-d137-4a84-8ce5-203b1e03b4c3-3.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day/gallery/5053efed-d137-4a84-8ce5-203b1e03b4c3-4.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day/gallery/5053efed-d137-4a84-8ce5-203b1e03b4c3-5.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day/gallery/5053efed-d137-4a84-8ce5-203b1e03b4c3-6.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day/gallery/5053efed-d137-4a84-8ce5-203b1e03b4c3-7.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day/gallery/5053efed-d137-4a84-8ce5-203b1e03b4c3-8.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day/gallery/5053efed-d137-4a84-8ce5-203b1e03b4c3-9.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day/gallery/5053efed-d137-4a84-8ce5-203b1e03b4c3-10.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day/gallery/5053efed-d137-4a84-8ce5-203b1e03b4c3-11.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day/gallery/5053efed-d137-4a84-8ce5-203b1e03b4c3-12.webp","h