INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('a95141f2-349e-458a-9605-09dd12c8746f', 'Visiting Hometown', 'visiting-hometown', '', 'Taking our little one back to our home town felt like taking him into a small piece of our own childhood. ❤️🌾

Surrounded by open fields, fresh air, green crops, and the simplicity of village life, we wanted him to see a world beyond the one he knows at home.

We showed him the crops, the soil, and the land that gives us so much. We wanted those tiny curious eyes to see where food comes from, how plants grow from little seeds, and how much patience and hard work goes into every harvest.

For us, it wasn’t just a visit to the fields. It was about introducing him to our roots and letting him experience the beauty of the land we grew up knowing.

One day, he may not remember this particular evening. But we will.

We’ll remember holding him among the crops, watching him take everything in with curiosity, and feeling grateful that we could share a little piece of our world with him.

Today, we weren’t just teaching him about crops and land. We were teaching him about his roots. 🌱❤️

And perhaps someday, when he looks back at these pictures, he’ll know that long before he understood the world, we were already trying to show him where he came from. ❤️', '2025-10-25', '', 'toddler', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visiting-hometown/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visiting-hometown/gallery/a95141f2-349e-458a-9605-09dd12c8746f-0.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visiting-hometown/gallery/a95141f2-349e-458a-9605-09dd12c8746f-1.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visiting-hometown/gallery/a95141f2-349e-458a-9605-09dd12c8746f-2.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visiting-hometown/gallery/a95141f2-349e-458a-9605-09dd12c8746f-3.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visiting-hometown/gallery/a95141f2-349e-458a-9605-09dd12c8746f-4.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visiting-hometown/gallery/a95141f2-349e-458a-9605-09dd12c8746f-5.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visiting-hometown/gallery/a95141f2-349e-458a-9605-09dd12c8746f-6.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visiting-hometown/gallery/a95141f2-349e-458a-9605-09dd12c8746f-7.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visiting-hometown/gallery/a95141f2-349e-458a-9605-09dd12c8746f-8.webp","https://fbfdwmlqoxfcqhodldpw.supabase.co/storage/v1/object/public/timeline/visiting-hometown/gallery/1786860530753-s6b5xwfu.jpg","https://fbfdwmlqoxfcqhodldpw.supabase.co/storage/v1/object/public/timeline/visiting-hometown/gallery/1786860531123-16109hge.jpg","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visiting-hometown/gallery/a95141f2-349e-458a-960