INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('2fcdad9a-1dd8-4d7f-b346-ba6ceb62eac8', 'Learning to Walk', 'learning-to-walk', '', 'Every day brings a new little adventure, and right now, you are learning one of the biggest things of all—how to walk! 👣❤️
You are still finding your balance, taking tiny steps, wobbling a little, and figuring out how these little feet are supposed to work. Sometimes you hold on for support, sometimes you take a brave step on your own, and every attempt makes me a little more confident.

There may be a few wobbles and falls along the way, but that’s all part of the journey. Every little step is bringing you closer to those confident first walks.

For now, you are taking it one step at a time… slowly discovering the world from a whole new height. 🥰

Little feet. Tiny steps. Big dreams. And a whole world waiting to be explored. 👣✨', '2025-10-03', '', 'toddler', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/learning-to-walk/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/learning-to-walk/gallery/2fcdad9a-1dd8-4d7f-b346-ba6ceb62eac8-0.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/learning-to-walk/gallery/2fcdad9a-1dd8-4d7f-b346-ba6ceb62eac8-1.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/learning-to-walk/gallery/2fcdad9a-1dd8-4d7f-b346-ba6ceb62eac8-2.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/learning-to-walk/gallery/2fcdad9a-1dd8-4d7f-b346-ba6ceb62eac8-3.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/learning-to-walk/gallery/2fcdad9a-1dd8-4d7f-b346-ba6ceb62eac8-4.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/learning-to-walk/gallery/2fcdad9a-1dd8-4d7f-b346-ba6ceb62eac8-5.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/learning-to-walk/gallery/2fcdad9a-1dd8-4d7f-b346-ba6ceb62eac8-6.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/learning-to-walk/gallery/2fcdad9a-1dd8-4d7f-b346-ba6ceb62eac8-7.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/learning-to-walk/gallery/2fcdad9a-1dd8-4d7f-b346-ba6ceb62eac8-8.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/learning-to-walk/gallery/2fcdad9a-1dd8-4d7f-b346-ba6ceb62eac8-9.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/learning-to-walk/gallery/2fcdad9a-1dd8-4d7f-b346-ba6ceb62eac8-10.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/learning-to-walk/gallery/2fcdad9a-1dd8-4d7f-b346-ba6ceb62eac8-11.webp","https://azain-media-worker.aaawaizshaikh.workers