INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('e475bec5-ee6a-4a79-9493-ed31d3e237bc', 'Beach Day Again...', 'beach-day-again', '', 'Beach Day Again

Today, we took you to the beach again, and it was as special as ever. The moment we arrived, the sea breeze greeted us,

the endless waves called out to us,

and we knew it was going to be a beautiful day.

We held your little hand and walked with you on the soft, wet sand, and it was the first time you truly walked on the beach. You were so curious, looking down at the sand, feeling it squish under your tiny feet.

Then came the magical moment-

the waves came rushing in, and the cool water touched your feet. You froze for a second, looked down in surprise, and then your face lit up with the biggest smile! It was like you discovered a whole new world.

You kept looking at the water, trying to touch it with your hands, splashing a little, giggling a lot. The waves would come and go,

but your joy stayed with us the entire time.

You collected tiny shells, pointed at the birds flying above, and watched the boats in the distance with wonder in your eyes. Every little thing amazed you,

and every moment with you felt like a gift.

♡

By the end of the day, your feet were sandy,

your cheeks were rosy,

and your heart was full.

You didn''t want to leave,

and honestly, neither did we!

Days like these remind us how the simplest moments become the most unforgettable memories. Your wonder, your laughter, your little footsteps on the beach- we will cherish them forever.', '2026-02-02', '', 'toddler', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day-again/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day-again/gallery/e475bec5-ee6a-4a79-9493-ed31d3e237bc-0.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day-again/gallery/e475bec5-ee6a-4a79-9493-ed31d3e237bc-1.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day-again/gallery/e475bec5-ee6a-4a79-9493-ed31d3e237bc-2.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day-again/gallery/e475bec5-ee6a-4a79-9493-ed31d3e237bc-3.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day-again/gallery/e475bec5-ee6a-4a79-9493-ed31d3e237bc-4.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/beach-day-again/gallery/e475bec5-ee6a-4a79-9493-ed31d3e237bc-5.mp4"]', '[]', 0, 1, 'beach-day-again', '2026-08-16T11:23:17.663781+00:00', '2026-08-21T13:02:18.19267+00:00', NULL, NULL, 'memory');
INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('30314e7a-01df-4b79-b97c-64a0f3fc9f46', 'Special Day Begins...', 'special-day-begins', '', '12:00 AM… and the special day begins. 🌙✨

The house is quiet, the clock strikes midnight, and suddenly… it’s your 1st birthday! 🎂💙

One whole year ago, you came into our lives and filled every ordinary day with extraordinary happiness. Tonight feels different — because this isn’t just another night. It’s the night we begin celebrating ONE beautiful year of you. 🥹❤️

Surrounded by balloons, little lights and all our love, our tiny birthday boy is ready to step into his very first birthday morning.

From your very first smile to your first steps, your little adventures, your laughter and all those precious moments in between — this year has given us memories we will cherish forever.

12:00 AM.
Your special day has begun.
And our little star is officially ONE. ⭐🎂

Happy 1st Birthday, Master Azain.
