INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('8ee7e5de-7cf3-4eac-9fee-c4d8d21e1250', 'Every day a new beginning ', 'every-day-a-new-beginning', '', 'Every Day, A New Beginning 🌿✨

Some of the most beautiful memories were never planned. They were simply ordinary days made extraordinary by your little smiles, curious eyes, funny expressions, new sounds, tiny discoveries, and all the unexpected moments that made us stop and say, “We have to remember this.”

Every day brought something new—another little milestone, another adventure, another glimpse of the wonderful person you were becoming. And while we thought we were just living through everyday moments, we were actually collecting memories that would one day mean everything to us.

Every day was a new beginning. Every day was a new adventure. And the best part of every day was always you. 🤍', '2025-03-05', '', 'infant', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/every-day-a-new-beginning/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/every-day-a-new-beginning/gallery/8ee7e5de-7cf3-4eac-9fee-c4d8d21e1250-0.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/every-day-a-new-beginning/gallery/8ee7e5de-7cf3-4eac-9fee-c4d8d21e1250-1.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/every-day-a-new-beginning/gallery/8ee7e5de-7cf3-4eac-9fee-c4d8d21e1250-2.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/every-day-a-new-beginning/gallery/8ee7e5de-7cf3-4eac-9fee-c4d8d21e1250-3.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/every-day-a-new-beginning/gallery/8ee7e5de-7cf3-4eac-9fee-c4d8d21e1250-4.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/every-day-a-new-beginning/gallery/8ee7e5de-7cf3-4eac-9fee-c4d8d21e1250-5.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/every-day-a-new-beginning/gallery/8ee7e5de-7cf3-4eac-9fee-c4d8d21e1250-6.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/every-day-a-new-beginning/gallery/8ee7e5de-7cf3-4eac-9fee-c4d8d21e1250-7.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/every-day-a-new-beginning/gallery/8ee7e5de-7cf3-4eac-9fee-c4d8d21e1250-8.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/every-day-a-new-beginning/gallery/8ee7e5de-7cf3-4eac-9fee-c4d8d21e1250-9.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/every-day-a-new-beginning/gallery/8ee7e5de-7cf3-4eac-9fee-c4d8d21e1250-10.webp","https://azain-media-worker.aaawaizshaikh.worker