INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('0b746544-143c-4245-a89a-1fb944051dad', 'Moments to cherish', 'moments-to-cherish', '', 'There are moments in life that seem so simple, yet somehow become the ones we treasure the most. A little time together, a smile, a hug, a familiar face waiting at home—these are the moments that turn an ordinary day into something beautiful.

Every moment with you turns into happiness. Every day, coming back home to you makes all the stress of the day slowly disappear, because in your little world there is only love, laughter, and peace.

One day, you may not remember these little moments, but we will. We will remember the way you sat beside us, the way you looked at us, and how even the smallest moments with you made everything feel right.

These are the moments we will cherish forever—because in these little moments, we find our biggest happiness. ❤️', '2025-05-08', '', 'infant', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/moments-to-cherish/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/moments-to-cherish/gallery/0b746544-143c-4245-a89a-1fb944051dad-0.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/moments-to-cherish/gallery/0b746544-143c-4245-a89a-1fb944051dad-1.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/moments-to-cherish/gallery/0b746544-143c-4245-a89a-1fb944051dad-2.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/moments-to-cherish/gallery/0b746544-143c-4245-a89a-1fb944051dad-3.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/moments-to-cherish/gallery/0b746544-143c-4245-a89a-1fb944051dad-4.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/moments-to-cherish/gallery/0b746544-143c-4245-a89a-1fb944051dad-5.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/moments-to-cherish/gallery/0b746544-143c-4245-a89a-1fb944051dad-6.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/moments-to-cherish/gallery/0b746544-143c-4245-a89a-1fb944051dad-7.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/moments-to-cherish/gallery/0b746544-143c-4245-a89a-1fb944051dad-8.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/moments-to-cherish/gallery/0b746544-143c-4245-a89a-1fb944051dad-9.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/moments-to-cherish/gallery/0b746544-143c-4245-a89a-1fb944051dad-10.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/moments-to-cherish/gallery/0b746544-143c-4245-a89a-1fb944051dad-1