INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('4d9d4615-bd64-4659-8991-fce1e31f984d', '6 Months of you..', '6-months-of-you', '', 'Half a year ago, you arrived and filled our lives with a love we could never have imagined. Today, we celebrate six beautiful months of your smiles, your little discoveries, your growing personality, and all the precious moments that have quietly become our favorite memories.

Dressed in white, surrounded by prayer, blessings, and so much love, this moment feels especially meaningful. May your journey always be filled with faith, kindness, happiness, and countless reasons to smile.

Six months of you, our little blessing—and a lifetime of beautiful memories still waiting to unfold. 🌙🤍', '2025-03-14', '', 'infant', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/6-months-of-you/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/6-months-of-you/gallery/4d9d4615-bd64-4659-8991-fce1e31f984d-0.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/6-months-of-you/gallery/4d9d4615-bd64-4659-8991-fce1e31f984d-1.webp","https://fbfdwmlqoxfcqhodldpw.supabase.co/storage/v1/object/public/timeline/6-months-of-you/gallery/1786737745748-158rqin3.jpg","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/6-months-of-you/gallery/4d9d4615-bd64-4659-8991-fce1e31f984d-3.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/6-months-of-you/gallery/4d9d4615-bd64-4659-8991-fce1e31f984d-4.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/6-months-of-you/gallery/4d9d4615-bd64-4659-8991-fce1e31f984d-5.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/6-months-of-you/gallery/4d9d4615-bd64-4659-8991-fce1e31f984d-6.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/6-months-of-you/gallery/4d9d4615-bd64-4659-8991-fce1e31f984d-7.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/6-months-of-you/gallery/4d9d4615-bd64-4659-8991-fce1e31f984d-8.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/6-months-of-you/gallery/4d9d4615-bd64-4659-8991-fce1e31f984d-9.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/6-months-of-you/gallery/4d9d4615-bd64-4659-8991-fce1e31f984d-10.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/6-months-of-you/gallery/4d9d4615-bd64-4659-8991-fce1e31f984d-11.webp","https://azain-media-worker.aaawaizshaikh.work