INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('c8ee00cd-4ae5-4be6-83b5-2db3fb5cdedc', 'School Bag', 'school-bag', '', 'Today was a very special day - you got your very first school bag! You were so excited to wear it, your eyes shining with happiness.

You kept asking to wear it again and again, and finally, the moment came!

As soon as you put it on, your face lit up like a star. You felt so big, so proud and so ready for all the amazing things ahead!

Dream big, learn more, shine bright!

You were excited to wear it, so excited that you didn''t want to take it off - not even for a minute! Since then, it has become your little buddy.

Always Carrying Along! From home to the park, from nani''s house to a family visit, you carry your bag everywhere you go! It holds not just your things, but your dreams, your curiosity and your big little hopes!

Here''s to new beginnings,', '2026-08-12', '', 'toddler', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/school-bag/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/school-bag/gallery/c8ee00cd-4ae5-4be6-83b5-2db3fb5cdedc-0.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/school-bag/gallery/c8ee00cd-4ae5-4be6-83b5-2db3fb5cdedc-1.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/school-bag/gallery/c8ee00cd-4ae5-4be6-83b5-2db3fb5cdedc-2.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/school-bag/gallery/c8ee00cd-4ae5-4be6-83b5-2db3fb5cdedc-3.webp"]', '[]', 0, 1, 'school-bag', '2026-08-16T18:43:06.463635+00:00', '2026-08-21T13:02:30.912013+00:00', NULL, NULL, 'memory');
