INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('7b0375aa-4b55-43e1-8c54-9c408c8d1416', 'Another day at beach', 'another-day-at-beach', '', 'Another day, another little adventure by the sea. 🌊❤️

Back at the beach, and once again, you were completely in your happy place. The moment you felt the sand between your little fingers and the cool water around your toes, you were ready to explore.

You played in the sand, splashed in the water, touched everything you could find, and enjoyed every little sensation around you. There was something so beautiful about watching you discover the beach in your own little way.

The breeze on your face, the sound of the waves, the wet sand beneath you, and that innocent curiosity in your eyes—every bit of it made the day special.

You laughed, you played, you explored… and most importantly, you enjoyed every moment. 🥰

Another beach day.
Another set of memories.
Another little piece of childhood we’ll cherish forever. ❤️🌊

Sand in your hands, water at your toes, and happiness written all over your little face.', '2025-11-14', '', 'toddler', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/another-day-at-beach/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/another-day-at-beach/gallery/7b0375aa-4b55-43e1-8c54-9c408c8d1416-0.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/another-day-at-beach/gallery/7b0375aa-4b55-43e1-8c54-9c408c8d1416-1.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/another-day-at-beach/gallery/7b0375aa-4b55-43e1-8c54-9c408c8d1416-2.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/another-day-at-beach/gallery/7b0375aa-4b55-43e1-8c54-9c408c8d1416-3.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/another-day-at-beach/gallery/7b0375aa-4b55-43e1-8c54-9c408c8d1416-4.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/another-day-at-beach/gallery/7b0375aa-4b55-43e1-8c54-9c408c8d1416-5.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/another-day-at-beach/gallery/7b0375aa-4b55-43e1-8c54-9c408c8d1416-6.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/another-day-at-beach/gallery/7b0375aa-4b55-43e1-8c54-9c408c8d1416-7.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/another-day-at-beach/gallery/7b0375aa-4b55-43e1-8c54-9c408c8d1416-8.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/another-day-at-beach/gallery/7b0375aa-4b55-43e1-8c54-9c408c8d1416-9.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/another-day-at-beach/gallery/7b0375aa-4b55-43e1-8c54-9c408c8d1416-10.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/another-day-at-beach/gallery/7b0375aa-4b55-43e1-8c54-9c408