INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('d3e84a93-5f9a-4dc1-b990-fec401365852', 'Three Hearts..One Happy World', 'three-hearts-one-happy-world', '', 'There''s nothing more special than our fun time together, just the three of us - Mom, Dad and you!

Your giggles, your excitement, the way you get so lost in your little world of toys and imagination... these are the moments that fill our hearts with so much

joy.

Whether it''s playing with your favorite cars, planes and bikes, or just spending time together, every little moment with you is a beautiful memory in the making.

You are our sunshine, our happiness and the reason behind our smiles.

Thank you for making our days so much brighter and our lives so much better.

We love you endlessly, always and forever! ♡', '2026-07-16', '', 'toddler', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/three-hearts-one-happy-world/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/three-hearts-one-happy-world/gallery/d3e84a93-5f9a-4dc1-b990-fec401365852-0.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/three-hearts-one-happy-world/gallery/d3e84a93-5f9a-4dc1-b990-fec401365852-1.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/three-hearts-one-happy-world/gallery/d3e84a93-5f9a-4dc1-b990-fec401365852-2.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/three-hearts-one-happy-world/gallery/d3e84a93-5f9a-4dc1-b990-fec401365852-3.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/three-hearts-one-happy-world/gallery/d3e84a93-5f9a-4dc1-b990-fec401365852-4.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/three-hearts-one-happy-world/gallery/d3e84a93-5f9a-4dc1-b990-fec401365852-5.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/three-hearts-one-happy-world/gallery/d3e84a93-5f9a-4dc1-b990-fec401365852-6.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/three-hearts-one-happy-world/gallery/d3e84a93-5f9a-4dc1-b990-fec401365852-7.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/three-hearts-one-happy-world/gallery/d3e84a93-5f9a-4dc1-b990-fec401365852-8.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/three-hearts-one-happy-world/gallery/d3e84a93-5f9a-4dc1-b990-fec401365852-9.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/three-hearts-one-happy-world/gallery/d3e84a93-5f9a-4dc1-b990-fec401365852-10.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/thre