INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('b2738886-44c2-4bc8-989d-b681d7edab69', 'Evening with Dada Dadi', 'evening-with-dada-dadi', '', 'Dada came back for a few days, and he decided to make those days extra special just for you. ❤️

What followed were some of the happiest evenings — filled with fun, laughter, little outings, endless stories, and plenty of cuddles. Every day became an opportunity for Dada to spend a little more time with you and create memories that would stay forever.

You loved being around him, and every moment together brought the biggest smiles. From being carried around and exploring new places to simply enjoying those quiet family moments, you made the most of every second.

Those evenings were not just about going out or having fun. They were about being together — making memories, sharing laughter, and filling your little world with love.

Dada came back for only a few days, but he made sure those days became some of your most special ones. 💙

The best memories are often the simplest ones — time spent together with the people we love. ❤️', '2026-04-10', '', 'toddler', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/evening-with-dada-dadi/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/evening-with-dada-dadi/gallery/b2738886-44c2-4bc8-989d-b681d7edab69-0.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/evening-with-dada-dadi/gallery/b2738886-44c2-4bc8-989d-b681d7edab69-1.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/evening-with-dada-dadi/gallery/b2738886-44c2-4bc8-989d-b681d7edab69-2.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/evening-with-dada-dadi/gallery/b2738886-44c2-4bc8-989d-b681d7edab69-3.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/evening-with-dada-dadi/gallery/b2738886-44c2-4bc8-989d-b681d7edab69-4.webp","https://fbfdwmlqoxfcqhodldpw.supabase.co/storage/v1/object/public/timeline/evening-with-dada-dadi/gallery/1786882608126-gepvydrl.jpg","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/evening-with-dada-dadi/gallery/b2738886-44c2-4bc8-989d-b681d7edab69-6.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/evening-with-dada-dadi/gallery/b2738886-44c2-4bc8-989d-b681d7edab69-7.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/evening-with-dada-dadi/gallery/b2738886-44c2-4bc8-989d-b681d7edab69-8.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/evening-with-dada-dadi/gallery/b2738886-44c2-4bc8-989d-b681d7edab69-9.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/evening-with-dada-dadi/gallery/b2738886-44c2-4bc8-989d-b681d7edab69-10.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/evening-with-dada-dadi/gallery/b2738886-44