INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('8b8444ef-6925-45ab-84bd-4fb4d7ef98c5', 'Celebration of One Magical Year', 'celebration-of-one-magical-year', '', 'A Day We’ll Cherish Forever 🎂💙

And finally, the moment we had been waiting for… your very first birthday celebration! 🥹✨

Surrounded by balloons, colours, cake and so much love, our little Azain celebrated ONE beautiful year of life, laughter and endless happiness. 🎈🎂

Mommy and Daddy stood beside you, holding their greatest blessing close — watching the little baby who once fit so perfectly in their arms grow into this cheerful, curious and wonderful little boy.

There were smiles, photographs, cake, hugs and countless little moments that made the day unforgettable. ❤️

But beyond all the decorations and celebrations, the most beautiful part was simply having you with us.

One year of you.
One year of memories.
One year of discovering a happiness we never knew existed.

Happy 1st Birthday, our little Prince Azain. 👑💙
May this be the first of countless birthdays filled with love, laughter and beautiful adventures.', '2025-09-14', '', 'infant', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/celebration-of-one-magical-year/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/celebration-of-one-magical-year/gallery/8b8444ef-6925-45ab-84bd-4fb4d7ef98c5-0.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/celebration-of-one-magical-year/gallery/8b8444ef-6925-45ab-84bd-4fb4d7ef98c5-1.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/celebration-of-one-magical-year/gallery/8b8444ef-6925-45ab-84bd-4fb4d7ef98c5-2.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/celebration-of-one-magical-year/gallery/8b8444ef-6925-45ab-84bd-4fb4d7ef98c5-3.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/celebration-of-one-magical-year/gallery/8b8444ef-6925-45ab-84bd-4fb4d7ef98c5-4.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/celebration-of-one-magical-year/gallery/8b8444ef-6925-45ab-84bd-4fb4d7ef98c5-5.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/celebration-of-one-magical-year/gallery/8b8444ef-6925-45ab-84bd-4fb4d7ef98c5-6.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/celebration-of-one-magical-year/gallery/8b8444ef-6925-45ab-84bd-4fb4d7ef98c5-7.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/celebration-of-one-magical-year/gallery/8b8444ef-6925-45ab-84bd-4fb4d7ef98c5-8.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/celebration-of-one-magical-year/gallery/8b8444ef-6925-45ab-84bd-4fb4d7ef98c5-9.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/celebration-of-one-magical-year/gallery/8b8444ef-6925-45ab-84bd-4fb4d7ef98c5-10.webp