INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('b014d439-c531-4df7-8171-deaf9cc4eb6d', 'Visit to Zoo..', 'visit-to-zoo', '', 'A Fun Day at the Zoo 🐘🦒❤️

Today was a special day at the zoo, and you enjoyed every single moment of it! We took you along with your Khalas, and right from the beginning, you were filled with excitement and curiosity.

As you saw the animals up close, you were completely mesmerised. Your eyes kept getting wider with every new animal—their size, their sounds, their movements, and all the little things they were doing seemed to amaze you. 🥰

You looked around with so much wonder, taking everything in and enjoying the experience to the fullest. And having your Khalas around made the day even more fun, with all the laughter, excitement, and little moments we shared together.

It wasn’t just a visit to the zoo; it was a whole day of discovering, learning, laughing, and making beautiful memories together.

A day filled with wild adventures, curious little eyes, lots of laughter, and the love of your Khala''s—a day we’ll cherish forever. ❤️🐒🦁🦒', '2026-02-11', '', 'toddler', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visit-to-zoo/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visit-to-zoo/gallery/b014d439-c531-4df7-8171-deaf9cc4eb6d-0.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visit-to-zoo/gallery/b014d439-c531-4df7-8171-deaf9cc4eb6d-1.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visit-to-zoo/gallery/b014d439-c531-4df7-8171-deaf9cc4eb6d-2.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visit-to-zoo/gallery/b014d439-c531-4df7-8171-deaf9cc4eb6d-3.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visit-to-zoo/gallery/b014d439-c531-4df7-8171-deaf9cc4eb6d-4.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visit-to-zoo/gallery/b014d439-c531-4df7-8171-deaf9cc4eb6d-5.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visit-to-zoo/gallery/b014d439-c531-4df7-8171-deaf9cc4eb6d-6.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visit-to-zoo/gallery/b014d439-c531-4df7-8171-deaf9cc4eb6d-7.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visit-to-zoo/gallery/b014d439-c531-4df7-8171-deaf9cc4eb6d-8.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visit-to-zoo/gallery/b014d439-c531-4df7-8171-deaf9cc4eb6d-9.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/visit-to-zoo/gallery/b014d439-c531-4df7-8171-deaf9cc4eb6d-10.webp","https://fbfdwmlqoxfcqhodldpw.supabase.co/storage/v1/object/public/timeline/visit-to-zoo/gallery/1786880919602-ogss3ohu.jpg","https://azain-media-worker.aaawaizshaikh.workers.