INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('96488ceb-b23f-47f7-95e0-0ea84e5010be', 'The Day you came to our world.', 'the-day-you-came-to-our-world', 'The day you were born', 'The day you were born, our world quietly changed forever.
Tiny fingers, a little hand holding ours, and a love bigger than we could ever put into words. You were so small, yet somehow you filled our entire world.
This was the very first memory we made with you — the first touch, the first little moment, and the beginning of your beautiful story.
Welcome to the world, our little one. This is where your story begins. ❤️', '2024-09-14', '', 'newborn', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-day-you-came-to-our-world/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-day-you-came-to-our-world/gallery/96488ceb-b23f-47f7-95e0-0ea84e5010be-0.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-day-you-came-to-our-world/gallery/96488ceb-b23f-47f7-95e0-0ea84e5010be-1.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-day-you-came-to-our-world/gallery/96488ceb-b23f-47f7-95e0-0ea84e5010be-2.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-day-you-came-to-our-world/gallery/96488ceb-b23f-47f7-95e0-0ea84e5010be-3.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-day-you-came-to-our-world/gallery/96488ceb-b23f-47f7-95e0-0ea84e5010be-4.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-day-you-came-to-our-world/gallery/96488ceb-b23f-47f7-95e0-0ea84e5010be-5.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-day-you-came-to-our-world/gallery/96488ceb-b23f-47f7-95e0-0ea84e5010be-6.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-day-you-came-to-our-world/gallery/96488ceb-b23f-47f7-95e0-0ea84e5010be-7.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-day-you-came-to-our-world/gallery/96488ceb-b23f-47f7-95e0-0ea84e5010be-8.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-day-you-came-to-our-world/gallery/96488ceb-b23f-47f7-95e0-0ea84e5010be-9.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-day-you-came-to-our-world/gallery/96488ceb-b23f-47f7-95e0-0ea84e5010be-10.webp","https://azain-media-worker.aaawaizs