INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('b81c66c3-9b3d-4c62-a10e-a0a59c617ddb', 'Home Coming....', 'home-coming', '', 'Today, you came home for the very first time, and suddenly, home felt a little more complete. ❤️
Wrapped in our arms and surrounded by love, you began your journey with us — filling our hearts with a happiness we never knew existed.
Your tiny presence has made our world bigger, brighter, and infinitely more beautiful.
Welcome home, little one.
This is the beginning of our forever with you. 🩵', '2024-09-18', '', 'newborn', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/home-coming/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/home-coming/gallery/b81c66c3-9b3d-4c62-a10e-a0a59c617ddb-0.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/home-coming/gallery/b81c66c3-9b3d-4c62-a10e-a0a59c617ddb-1.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/home-coming/gallery/b81c66c3-9b3d-4c62-a10e-a0a59c617ddb-2.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/home-coming/gallery/b81c66c3-9b3d-4c62-a10e-a0a59c617ddb-3.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/home-coming/gallery/b81c66c3-9b3d-4c62-a10e-a0a59c617ddb-4.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/home-coming/gallery/b81c66c3-9b3d-4c62-a10e-a0a59c617ddb-5.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/home-coming/gallery/b81c66c3-9b3d-4c62-a10e-a0a59c617ddb-6.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/home-coming/gallery/b81c66c3-9b3d-4c62-a10e-a0a59c617ddb-7.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/home-coming/gallery/b81c66c3-9b3d-4c62-a10e-a0a59c617ddb-8.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/home-coming/gallery/b81c66c3-9b3d-4c62-a10e-a0a59c617ddb-9.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/home-coming/gallery/b81c66c3-9b3d-4c62-a10e-a0a59c617ddb-10.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/home-coming/gallery/b81c66c3-9b3d-4c62-a10e-a0a59c617ddb-11.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/home-coming/gallery/b81c66c3-9b3d-4c62-a10e-a0a59c617ddb-12.w