aikh.workers.dev/media/media/memories/home-coming/gallery/b81c66c3-9b3d-4c62-a10e-a0a59c617ddb-27.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/home-coming/gallery/b81c66c3-9b3d-4c62-a10e-a0a59c617ddb-28.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/home-coming/gallery/b81c66c3-9b3d-4c62-a10e-a0a59c617ddb-29.webp"]', '[]', 0, 1, 'home-coming', '2026-08-11T16:23:40.126061+00:00', '2026-08-21T13:03:30.527626+00:00', NULL, NULL, 'memory');
INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('b2ba6787-eef9-426f-b9ed-96c1f9f41247', 'One Month Of You', 'one-month-of-you', '', 'One tiny month, yet you’ve already filled our hearts with a lifetime of love. 🥰
Your little smiles, curious eyes, tiny hands and all those precious moments have made our world brighter than ever. Watching you grow, even day by day, feels like witnessing a little miracle unfold. ✨
Today we celebrate one beautiful month of you — one month of cuddles, sleepless nights, countless memories and a love that grows stronger every single day.
May your journey ahead be filled with happiness, laughter, good health and endless blessings. ❤️
Happy 1 Month, our little one!
You are tiny today, but you have already made our world wonderfully big. 🌙🧸✨', '2024-10-14', '', 'newborn', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/one-month-of-you/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/one-month-of-you/gallery/b2ba6787-eef9-426f-b9ed-96c1f9f41247-0.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/one-month-of-you/gallery/b2ba6787-eef9-426f-b9ed-96c1f9f41247-1.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/one-month-of-you/gallery/b2ba6787-eef9-426f-b9ed-96c1f9f41247-2.webp","https://fbfdwmlqoxfcqhodldpw.supabase.co/storage/v1/object/public/timeline/one-month-of-you/gallery/1786466136135-tx5p0air.jpg","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/one-month-of-you/gallery/b2ba6787-eef9-426f-b9ed-96c1f9f41247-4.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/one-month-of-you/gallery/b2ba6787-eef9-426f-b9ed-96c1f9f41247-5.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/one-month-of-you/gallery/b2ba6787-eef9-426f-b9ed-96c1f9f41247-6.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/one-month-of-you/gallery/b2ba6787-eef9-426f-b9ed-96c1f9f41247-7.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/one-month-of-you/gallery/b2ba6787-eef9-426f-b9ed-96c1f9f41247-8.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/one-month-of-you/gallery/b2ba6787-eef9-426f-b9ed-96c1f9f41247-9.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/one-month-of-you/gallery/b2ba6787-eef9-426f-b9ed-96c1f9f41247-10.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/one-month-of-you/gallery/b2ba6787-eef9-426f-b9ed-96c1f9f41247-11.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media