INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('ac47e216-2eac-4583-9245-16ef14e82bc5', 'Happy Holi...', 'happy-holi', '', 'Today was our very own Holi celebration! Instead of colors, you played with soft, gentle baby powder safe, fun and oh-so-messy!

You had the biggest smile on your face the whole time, so happy, so excited, so full of joy!

Your favourite part? Definitely applying baby powder to chachu! You went all in with your tiny hands, patting, smearing and giggling non-stop. Every time chachu pretended to be shocked, you laughed even harder!

The flying powder, the silly faces, the tickles and the laughter - it was a Holi to remember forever. You made the day extra special with your little mischief and beautiful happiness.

Here''s to many more such moments with you, my little bundle of joy!', '2026-03-03', '', 'toddler', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/happy-holi/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/happy-holi/gallery/ac47e216-2eac-4583-9245-16ef14e82bc5-0.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/happy-holi/gallery/ac47e216-2eac-4583-9245-16ef14e82bc5-1.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/happy-holi/gallery/ac47e216-2eac-4583-9245-16ef14e82bc5-2.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/happy-holi/gallery/ac47e216-2eac-4583-9245-16ef14e82bc5-3.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/happy-holi/gallery/ac47e216-2eac-4583-9245-16ef14e82bc5-4.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/happy-holi/gallery/ac47e216-2eac-4583-9245-16ef14e82bc5-5.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/happy-holi/gallery/ac47e216-2eac-4583-9245-16ef14e82bc5-6.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/happy-holi/gallery/ac47e216-2eac-4583-9245-16ef14e82bc5-7.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/happy-holi/gallery/ac47e216-2eac-4583-9245-16ef14e82bc5-8.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/happy-holi/gallery/ac47e216-2eac-4583-9245-16ef14e82bc5-9.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/happy-holi/gallery/ac47e216-2eac-4583-9245-16ef14e82bc5-10.webp"]', '[]', 0, 1, 'happy-holi', '2026-08-16T11:59:02.05331+00:00', '2026-08-21T13:03:34.094988+00:00', NULL, NULL, 'memory');
INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('fc547cc7-4b62-4b4e-8bcf-e860c1d04a33', 'Our Little Explorer Takes Off', 'our-little-explorer-takes-off', '', 'The day you started walking, it felt like a whole new world had opened up for you. And very quickly, we realized—you had absolutely no plans of slowing down! ❤️👣

Once those little feet figured out how to move, you wanted to go everywhere.

From one corner of the house to another, from one room to the next, down every road and towards every new thing that caught your attention—you were always on the move.

We would try to catch you, call you back, or keep an eye on where you were heading, but your curiosity was always one step ahead of us. 😄

Every corner became an adventure. Every road became a new path to explore. And every little thing you saw made you want to go a little further.

It was incredible watching that transformation—from those first uncertain, wobbly steps to this little explorer who simply wanted to run everywhere.

Your tiny legs suddenly had endless energy, and your curiosity seemed even bigger.

Looking back, we realize those first steps weren''t just the beginning of walking. They were the beginning of discovering the world on your own terms.

Once you started walking, there was no stopping you. You didn''t just learn to walk—you learned to explore, chase, discover, and keep going. ❤️

And we knew then that our job had changed too… from helping you take your first steps to trying our best to keep up with you! 😄👣', '2025-12-17', '', 'toddler', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/our-little-explorer-takes-off/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/our-little-explorer-takes-off/gallery/fc547cc7-4b62-4b4e-8bcf-e860c1d04a33-0.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/our-little-explorer-takes-off/gallery/fc547cc7-4b62-4b4e-8bcf-e860c1d04a33-1.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/our-little-explorer-takes-off/gallery/fc547cc7-4b62-4b4e-8bcf-e860c1d04a33-2.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/our-little-explorer-takes-off/gallery/fc547cc7-4b62-4b4e-8bcf-e860c1d04a33-3.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/our-little-explorer-takes-off/gallery/fc547cc7-4b62-4b4e-8bcf-e860c1d04a33-4.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/our-little-explorer-takes-off/gallery/fc547cc7-4b62-4b4e-8bcf-e860c1d04a33-5.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/our-little-explorer-takes-off/gallery/fc547cc7-4b62-4b4e-8bcf-e860c1d04a33-6.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/our-little-explorer-takes-off/gallery/fc547cc7-4b62-4b4e-8bcf-e860c1d04a33-7.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/our-little-explorer-takes-off/gallery/fc547cc7-4b62-4b4e-8bcf-e860c1d04a33-8.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/our-little-explorer-takes-off/gallery/fc547cc7-4b62-4b4e-8bcf-e860c1d04a33-9.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/our-little-explorer-takes-off/gallery/fc547cc7-4b62-4b4e-8bcf-e860c1d04