INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('8334c87d-dae7-469b-9561-a4319216e7ed', '3 months of you', '3-months-of-you', '', 'Three Months of You

Three months ago, you came into our lives and quietly changed everything.

In just ninety little days, you have filled our home with tiny sounds, sleepy smiles, curious eyes, and a kind of love we never knew could grow so big, so quickly.

We still remember the first time your tiny fingers wrapped around ours. Today, those little fingers are already holding on a little tighter — as if you’re telling us, “I’m here, and I’m not letting go.”

Every day with you feels like a new little adventure.
A new expression.
A new sound.
A new smile.
A new memory to keep forever.

You may only be three months old, but you have already given us a lifetime of moments we never want to forget.

So today, we celebrate you — our tiny bundle of love, our sweetest little miracle, and the beautiful beginning of your story.

Happy 3rd Month Birthday, little one.

Three months down, and a whole beautiful world of memories waiting ahead. 🤍', '2024-12-14', '', 'newborn', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/3-months-of-you/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/3-months-of-you/gallery/8334c87d-dae7-469b-9561-a4319216e7ed-0.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/3-months-of-you/gallery/8334c87d-dae7-469b-9561-a4319216e7ed-1.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/3-months-of-you/gallery/8334c87d-dae7-469b-9561-a4319216e7ed-2.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/3-months-of-you/gallery/8334c87d-dae7-469b-9561-a4319216e7ed-3.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/3-months-of-you/gallery/8334c87d-dae7-469b-9561-a4319216e7ed-4.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/3-months-of-you/gallery/8334c87d-dae7-469b-9561-a4319216e7ed-5.webp"]', '[]', 0, 1, '3-months-of-you', '2026-08-14T16:39:18.732897+00:00', '2026-08-21T13:03:42.535116+00:00', NULL, NULL, 'memory');
INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('b480bed2-bdf8-4566-b39d-ea66aa0c13c6', 'Habibi', 'habibi', '', '
You may not have known it yet, but you were already the star of the show.

Sitting there in your little traditional outfit, looking straight into the camera with those curious eyes, you somehow made the whole moment feel bigger than a simple photograph.

We wanted to capture more than just how cute you looked that day.

We wanted to capture this version of you —
so small, so innocent, so curious, and already carrying so much personality.

One day, you''ll look back at these pictures and laugh at how tiny you were.

But for us, this isn''t just a photo.

It''s a little piece of your childhood, frozen in time.

All dressed up.
All ready for the camera.
And already stealing everyone''s hearts. 🤍

Our little star had his first photo shoot — and, of course, he absolutely owned it. ✨', '2025-01-10', '', 'infant', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/habibi/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/habibi/gallery/b480bed2-bdf8-4566-b39d-ea66aa0c13c6-0.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/habibi/gallery/b480bed2-bdf8-4566-b39d-ea66aa0c13c6-1.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/habibi/gallery/b480bed2-bdf8-4566-b39d-ea66aa0c13c6-2.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/habibi/gallery/b480bed2-bdf8-4566-b39d-ea66aa0c13c6-3.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/habibi/gallery/b480bed2-bdf8-4566-b39d-ea66aa0c13c6-4.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/habibi/gallery/b480bed2-bdf8-4566-b39d-ea66aa0c13c6-5.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/habibi/gallery/b480bed2-bdf8-4566-b39d-ea66aa0c13c6-6.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/habibi/gallery/b480bed2-bdf8-4566-b39d-ea66aa0c13c6-7.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/habibi/gallery/b480bed2-bdf8-4566-b39d-ea66aa0c13c6-8.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/habibi/gallery/b480bed2-bdf8-4566-b39d-ea66aa0c13c6-9.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/habibi/gallery/b480bed2-bdf8-4566-b39d-ea66aa0c13c6-10.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/habibi/gallery/b480bed2-bdf8-4566-b39d-ea66aa0c13c6-11.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/habibi/gallery/b480bed2-bdf8-4566-b39d-ea66aa0c13c6-12.webp","https://azain-media-worker.a