INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('6e0cda52-885a-4b9a-ac75-4ff135f0b926', 'The Little Moments We Keep', 'the-little-moments-we-keep', '', '

Some of our most precious memories were never planned.

They were the random videos we took because you suddenly smiled.
The little sounds you made when you were wide awake at bedtime.
The sleepy cuddles we never wanted to end.
The funny expressions that made us reach for the phone before the moment disappeared.

Sometimes it was just you looking at us.
Sometimes it was a tiny yawn, a curious stare, a little movement, or simply the way you rested in our arms.

They may look like ordinary moments to everyone else, but to us, they are everything.

Because childhood isn''t made only of big celebrations and perfect photographs. It''s made of these tiny, unexpected pieces of life — the moments we almost didn''t notice, but somehow became the memories we treasure most.

And as you grow, these little videos and photographs will become our way of going back.

Back to your tiny hands.
Back to your little voice.
Back to the way you fit perfectly in our arms.
Back to these beautiful days when you were still so small.

Three months of you, and already a thousand memories worth keeping.

So here''s to every random video, every imperfect photograph, every silly moment, every cuddle, every smile — and every little memory that quietly became special simply because you were in it.

You are growing up every day.
We''ll keep the moments forever. 🤍', '2024-10-17', '', 'newborn', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-little-moments-we-keep/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-little-moments-we-keep/gallery/6e0cda52-885a-4b9a-ac75-4ff135f0b926-0.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-little-moments-we-keep/gallery/6e0cda52-885a-4b9a-ac75-4ff135f0b926-1.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-little-moments-we-keep/gallery/6e0cda52-885a-4b9a-ac75-4ff135f0b926-2.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-little-moments-we-keep/gallery/6e0cda52-885a-4b9a-ac75-4ff135f0b926-3.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-little-moments-we-keep/gallery/6e0cda52-885a-4b9a-ac75-4ff135f0b926-4.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-little-moments-we-keep/gallery/6e0cda52-885a-4b9a-ac75-4ff135f0b926-5.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-little-moments-we-keep/gallery/6e0cda52-885a-4b9a-ac75-4ff135f0b926-6.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/the-little-moments-we-keep/gallery/6e0cda52-885a-4b9a-ac75-4ff135f0b926-7.mp4"]', '[]', 0, 1, 'the-little-moments-we-keep', '2026-08-14T16:50:09.723516+00:00', '2026-08-21T13:03:58.514072+00:00', NULL, NULL, 'memory');
INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('c6db3143-2eed-49ac-8e10-ba9695528a3f', 'Baby''s day out', 'baby-s-day-out', '', 'Today was your special Baby’s Day Out! 🌈💙

A day filled with play, laughter, and little adventures. You explored everything around you with those curious little eyes — from colorful activity boards to fun little games that kept you busy and fascinated. 🧩✨

And of course, no day out is complete without some slides and playground fun! 🛝 You were busy discovering, playing, climbing, and enjoying every little moment.

Watching you explore the world with so much curiosity made our hearts so happy. Every new thing you touched, every little game you played, and every smile along the way became another beautiful memory to treasure.

These may seem like simple moments today, but someday they will be the memories we look back on with the biggest smiles. ❤️

Baby’s Day Out — little adventures, happy hearts, and memories to cherish forever! 👶✨', '2026-03-02', '', 'toddler', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/baby-s-day-out/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/baby-s-day-out/gallery/c6db3143-2eed-49ac-8e10-ba9695528a3f-0.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/baby-s-day-out/gallery/c6db3143-2eed-49ac-8e10-ba9695528a3f-1.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/baby-s-day-out/gallery/c6db3143-2eed-49ac-8e10-ba9695528a3f-2.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/baby-s-day-out/gallery/c6db3143-2eed-49ac-8e10-ba9695528a3f-3.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/baby-s-day-out/gallery/c6db3143-2eed-49ac-8e10-ba9695528a3f-4.webp"]', '[]', 0, 1, 'baby-s-day-out', '2026-08-16T11:38:26.719093+00:00', '2026-08-21T13:04:32.662856+00:00', NULL, NULL, 'memory');
