INSERT OR IGNORE INTO timeline (id, title, slug, description, story, date, age, category, cover_image, gallery_images, highlights, favorite, published, folder_name, created_at, updated_at, book, book_type, memory_type) VALUES ('e3fe8f46-f6ed-495f-8ca8-a8780a45993b', 'Fun times...', 'fun-times', '', 'Fun Time — Little Rides, Big Smiles ❤️
Some of our favourite memories are made in the simplest moments—and this was definitely one of them.
You were so excited to sit on the bike, hold the handlebar, and feel like you were ready to go on your own little adventure. With Dad right behind you, keeping you safe, you couldn’t stop smiling and laughing. 🏍️🥰
Watching your tiny hands on the handlebar and that priceless happiness on your face made the moment even more special for us. It wasn’t really about the ride—it was about the fun, the excitement, and the joy of doing something together.
These are the moments we want to hold onto forever: your laughter, your curiosity, and the happiness you bring into even the simplest little adventures.
One day, you’ll have your own big rides and big adventures. But we’ll always remember when the smallest rides gave us the biggest smiles. ❤️
Little adventures today, beautiful memories forever. 🏍️✨', '2026-01-22', '', 'toddler', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/fun-times/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/fun-times/gallery/e3fe8f46-f6ed-495f-8ca8-a8780a45993b-0.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/fun-times/gallery/e3fe8f46-f6ed-495f-8ca8-a8780a45993b-1.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/fun-times/gallery/e3fe8f46-f6ed-495f-8ca8-a8780a45993b-2.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/fun-times/gallery/e3fe8f46-f6ed-495f-8ca8-a8780a45993b-3.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/fun-times/gallery/e3fe8f46-f6ed-495f-8ca8-a8780a45993b-4.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/fun-times/gallery/e3fe8f46-f6ed-495f-8ca8-a8780a45993b-5.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/fun-times/gallery/e3fe8f46-f6ed-495f-8ca8-a8780a45993b-6.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/fun-times/gallery/e3fe8f46-f6ed-495f-8ca8-a8780a45993b-7.webp","https://fbfdwmlqoxfcqhodldpw.supabase.co/storage/v1/object/public/timeline/fun-times/gallery/1786879713689-ny5vt1t3.jpg","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/fun-times/gallery/e3fe8f46-f6ed-495f-8ca8-a8780a45993b-9.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/fun-times/gallery/e3fe8f46-f6ed-495f-8ca8-a8780a45993b-10.webp","https://fbfdwmlqoxfcqhodldpw.supabase.co/storage/v1/object/public/timeline/fun-times/gallery/1786879715018-net8qbw5.jpg","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/memories/fun-times/gallery/e3fe8f46-f6ed-495f-8ca8-a8780a45993b-12.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/