INSERT OR IGNORE INTO milestones (id, created_at, title, slug, date, age, category, description, story, cover_image, gallery, highlights, favorite, published) VALUES ('d2651637-0c9b-40da-af70-71b204ba8710', '2026-08-14T19:43:42.324004+00:00', 'First Crawl', 'first-crawl', '2025-01-31', '', 'infant', '', 'Today, something magical happened—you discovered that you could move!

With your tiny hands reaching forward, little legs kicking behind you, and the biggest smile on your face, you started your very first crawl. What began as a few little wiggles soon turned into your first adventure across the floor.

You were so determined, so curious, and completely unaware that you had just reached another beautiful milestone.

Every little movement was a big achievement. Every crawl brought you closer to the world you were so eager to explore.

A little move for you, a giant leap for us. 💛

And just like that, your little journey of discovering the world on your own has begun. ✨', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-crawl/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-crawl/gallery/d2651637-0c9b-40da-af70-71b204ba8710-0.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-crawl/gallery/d2651637-0c9b-40da-af70-71b204ba8710-1.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-crawl/gallery/d2651637-0c9b-40da-af70-71b204ba8710-2.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-crawl/gallery/d2651637-0c9b-40da-af70-71b204ba8710-3.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-crawl/gallery/d2651637-0c9b-40da-af70-71b204ba8710-4.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-crawl/gallery/d2651637-0c9b-40da-af70-71b204ba8710-5.mp4"]', '[]', 0, 1);
INSERT OR IGNORE INTO milestones (id, created_at, title, slug, date, age, category, description, story, cover_image, gallery, highlights, favorite, published) VALUES ('79970880-f190-46d4-8d08-88da2b4e1115', '2026-08-16T11:47:44.361274+00:00', 'First Musical Instrument ', 'first-musical-instrument', '2026-03-05', '', 'toddler', '', 'Today was a day filled with music, laughter, and one very special little milestone — you were learning your first musical instrument: the harmonica! 🎶❤️

At first, you were simply curious, holding it in your tiny hands and figuring out what this little instrument could do. And then came your very first blow… and the sweetest little sound!

Every blow you made had us laughing with happiness. 😄 Every clap from us encouraged you to try again, and you happily kept going, determined to make more music. Before long, you were completely fascinated by it.

The happiest moment was watching your face light up each time you made a sound. You didn''t need a perfect melody — your little attempts were music enough for us. ❤️

And then came the most amazing part… by Day 2, you were already a little pro! 🎵 You knew exactly how to hold it, where to place it, and how to blow into it. Watching you pick it up with so much confidence made this tiny milestone even more special.

It wasn''t just about learning the harmonica. It was about discovering something new, finding joy in it, and sharing that joy with everyone around you.

Your first instrument, your first little melodies, and one beautiful memory we will cherish forever. 🎶💙', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-musical-instrument/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-musical-instrument/gallery/79970880-f190-46d4-8d08-88da2b4e1115-0.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-musical-instrument/gallery/79970880-f190-46d4-8d08-88da2b4e1115-1.mp4"]', '[]', 0, 1);
INSERT OR IGNORE INTO milestones (id, created_at, title, slug, date, age, category, description, story, cover_image, gallery, highlights, favorite, published) VALUES ('3c0d0dfa-00cf-4be9-98ad-a08379ab1b18', '2026-08-16T06:21:40.572716+00:00', 'First Step', 'first-step', '2025-12-04', '', 'toddler', '', 'Today was one of those days we knew we would remember forever. ❤️

We had watched you wobble, hold onto furniture, take tiny supported steps, and keep trying again and again. And then, suddenly, you were ready.

You started walking.

Those first little steps were wobbly and uncertain, but you had the biggest smile on your face—as if you already knew you had just accomplished something incredible. 👣🥰

We watched you take one step, then another, discovering that you could actually move forward all by yourself. For us, it was so much more than learning to walk. It was the beginning of a whole new chapter.

From now on, those little feet would take you places we could only imagine.

We know there will be many more steps ahead—some towards us, some away from us, some steady and some uncertain. But we hope you always carry the same courage and curiosity you had in those very first steps.

We may not remember every detail of this day years from now, but we will always remember how proud and emotional we felt watching our little one take his first steps.

Your first steps were tiny, but the milestone was enormous. And just like that, a whole new adventure began. ❤️👣', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-step/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-step/gallery/3c0d0dfa-00cf-4be9-98ad-a08379ab1b18-0.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-step/gallery/3c0d0dfa-00cf-4be9-98ad-a08379ab1b18-1.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-step/gallery/3c0d0dfa-00cf-4be9-98ad-a08379ab1b18-2.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-step/gallery/3c0d0dfa-00cf-4be9-98ad-a08379ab1b18-3.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-step/gallery/3c0d0dfa-00cf-4be9-98ad-a08379ab1b18-4.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-step/gallery/3c0d0dfa-00cf-4be9-98ad-a08379ab1b18-5.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-step/gallery/3c0d0dfa-00cf-4be9-98ad-a08379ab1b18-6.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-step/gallery/3c0d0dfa-00cf-4be9-98ad-a08379ab1b18-7.webp","https://fbfdwmlqoxfcqhodldpw.supabase.co/storage/v1/object/public/timeline/milestones/gallery/1786861299688-bgfby7m5.jpg","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-step/gallery/3c0d0dfa-00cf-4be9-98ad-a08379ab1b18-9.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-step/gallery/3c0d0dfa-00cf-4be9-98ad-a08379ab1b18-10.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-step/gallery/3c0d0dfa-00cf-4be9-98ad-a08379ab1b18-11.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-step/gallery/3c0d0dfa-00cf-4be9-98ad-a08379ab1b18-12.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-step/gallery/3c0d0dfa-00cf-4be9-98ad-a08379ab1b18-13.webp"]', '[]', 0, 1);
INSERT OR IGNORE INTO milestones (id, created_at, title, slug, date, age, category, description, story, cover_image, gallery, highlights, favorite, published) VALUES ('6257340a-001b-48b7-9a8a-437cbe36fc04', '2026-08-16T18:20:02.716223+00:00', 'First Rain', 'first-rain', '2026-07-09', '', 'toddler', '', 'Today was your first rain experience, and it was nothing short of magical!

The moment the first drops of rain touched your head, you were shocked! You stood still... completely frozen, with your eyes wide open and a million questions in your little eyes.

You didn''t move for a few minutes, just standing there... feeling the new, cool sensation.

You turned the rain into pure joy!

♡

But once you came back to your senses- oh, what a change! You ran everywhere! From one corner to another, laughing, squealing and trying to catch the raindrops like tiny treasures.

You twirled, you jumped, you splashed and you smiled... It was your own little monsoon adventure!

These little moments are the ones we will always hold close to our hearts.

Here''s to many more rainy day adventures!

♡', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-rain/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-rain/gallery/6257340a-001b-48b7-9a8a-437cbe36fc04-0.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-rain/gallery/6257340a-001b-48b7-9a8a-437cbe36fc04-1.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-rain/gallery/6257340a-001b-48b7-9a8a-437cbe36fc04-2.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-rain/gallery/6257340a-001b-48b7-9a8a-437cbe36fc04-3.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-rain/gallery/6257340a-001b-48b7-9a8a-437cbe36fc04-4.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-rain/gallery/6257340a-001b-48b7-9a8a-437cbe36fc04-5.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-rain/gallery/6257340a-001b-48b7-9a8a-437cbe36fc04-6.webp"]', '[]', 0, 1);
INSERT OR IGNORE INTO milestones (id, created_at, title, slug, date, age, category, description, story, cover_image, gallery, highlights, favorite, published) VALUES ('2a96bf64-f53e-41a1-97f9-33ac6bea2e1c', '2026-08-16T05:37:50.877562+00:00', 'First Time Standing ', 'first-time-standing', '2025-08-15', '', 'infant', '', 'Today was extra special—not just because it was Independence Day, but because I stood on my own for the very first time! 🇮🇳✨

With my little tricolour flag in my hand and a heart full of curiosity, I took my first proud steps into a brand-new milestone. A tiny moment for the world, but a memory that will stay in our hearts forever.

My first standing, on Independence Day—a beautiful beginning filled with freedom, courage, and endless possibilities. ❤️🇮🇳

A little patriot today, a big dreamer tomorrow.
Happy Independence Day! 🇮🇳✨', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-time-standing/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-time-standing/gallery/2a96bf64-f53e-41a1-97f9-33ac6bea2e1c-0.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-time-standing/gallery/2a96bf64-f53e-41a1-97f9-33ac6bea2e1c-1.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-time-standing/gallery/2a96bf64-f53e-41a1-97f9-33ac6bea2e1c-2.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-time-standing/gallery/2a96bf64-f53e-41a1-97f9-33ac6bea2e1c-3.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-time-standing/gallery/2a96bf64-f53e-41a1-97f9-33ac6bea2e1c-4.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-time-standing/gallery/2a96bf64-f53e-41a1-97f9-33ac6bea2e1c-5.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-time-standing/gallery/2a96bf64-f53e-41a1-97f9-33ac6bea2e1c-6.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-time-standing/gallery/2a96bf64-f53e-41a1-97f9-33ac6bea2e1c-7.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-time-standing/gallery/2a96bf64-f53e-41a1-97f9-33ac6bea2e1c-8.webp"]', '[]', 0, 1);
INSERT OR IGNORE INTO milestones (id, created_at, title, slug, date, age, category, description, story, cover_image, gallery, highlights, favorite, published) VALUES ('a50d41a2-a1d8-4072-8345-b43a6d844fe2', '2026-08-11T17:05:56.864912+00:00', 'First Roll Over', 'first-roll-over', '2025-01-14', '', 'newborn', '', 'You tried again and again, wiggling, stretching, pushing, and refusing to give up. And then, one beautiful moment… you finally did it! 🥹💙
Your very first roll over — a tiny milestone that felt like a giant victory for all of us. We watched your little determination turn into the biggest smile of pride.
One roll at a time, you’re discovering your world. And we’ll be here to cheer for every little adventure ahead. 🐣', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-roll-over/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-roll-over/gallery/a50d41a2-a1d8-4072-8345-b43a6d844fe2-0.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-roll-over/gallery/a50d41a2-a1d8-4072-8345-b43a6d844fe2-1.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-roll-over/gallery/a50d41a2-a1d8-4072-8345-b43a6d844fe2-2.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-roll-over/gallery/a50d41a2-a1d8-4072-8345-b43a6d844fe2-3.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-roll-over/gallery/a50d41a2-a1d8-4072-8345-b43a6d844fe2-4.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-roll-over/gallery/a50d41a2-a1d8-4072-8345-b43a6d844fe2-5.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-roll-over/gallery/a50d41a2-a1d8-4072-8345-b43a6d844fe2-6.webp","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/first-roll-over/gallery/a50d41a2-a1d8-4072-8345-b43a6d844fe2-7.webp"]', '[]', 0, 1);
INSERT OR IGNORE INTO milestones (id, created_at, title, slug, date, age, category, description, story, cover_image, gallery, highlights, favorite, published) VALUES ('6a50effd-76af-47a8-8a00-1774975c9093', '2026-08-20T06:02:11.482255+00:00', 'TEST', 'test', '2026-08-20', '', 'newborn', 'TEST', 'TEST', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/test/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/milestones/test/gallery/6a50effd-76af-47a8-8a00-1774975c9093-0.webp"]', '[]', 0, 1);

