INSERT OR IGNORE INTO favorite_songs (id, title, artist, month, age, slug, category, cover_image, gallery_images, video_url, story, highlights, display_order, favorite, created_at) VALUES ('82f72805-63bb-4862-911e-b6d5c76ab7e7', 'Hawa Jawa', '', 'July 2026', '', 'hawa-jawa', 'Favourite Song', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/songs/hawa-jawa/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/songs/hawa-jawa/gallery/82f72805-63bb-4862-911e-b6d5c76ab7e7-0.mp4"]', '', 'You discovered your new favourite song — “Hawa Hawa” by Hassan Jahangir! 🎶❤️ And once it started playing at home, there was no stopping you.

With Dadi by your side, you absolutely rocked this song! From dancing to enjoying every beat, your little Hawa Hawa sessions were filled with smiles, laughter, and so much energy. 🥰🎵

Dadi and you made the perfect little musical duo, turning an ordinary day at home into a fun-filled memory. These are the simple moments that become the sweetest memories forever. ❤️✨', '[]', 0, 0, '2026-08-16T17:54:31.060586+00:00');
INSERT OR IGNORE INTO favorite_songs (id, title, artist, month, age, slug, category, cover_image, gallery_images, video_url, story, highlights, display_order, favorite, created_at) VALUES ('e7d4a7a8-a58f-42e5-90f6-3d9153092281', 'Apate Apate', '', 'June 2026', '', 'apate-apate', 'Favourite Song', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/songs/apate-apate/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/songs/apate-apate/gallery/e7d4a7a8-a58f-42e5-90f6-3d9153092281-0.mp4"]', '', 'Ansha Khala introduced you to “Apate Apate” by Rosé & Bruno Mars, and after that, there was simply no stopping you! 🎶❤️ What started as one little introduction quickly became your new favourite song.

Soon, every time the song played, you were ready to enjoy the beat, sip your drink, and soak in the music. “Apate Apate” on repeat became your little thing — one of those adorable memories that will always remind us of Ansha Khala and the song she introduced you to. 🥰🎵✨', '[]', 0, 0, '2026-08-16T17:50:05.63608+00:00');
INSERT OR IGNORE INTO favorite_songs (id, title, artist, month, age, slug, category, cover_image, gallery_images, video_url, story, highlights, display_order, favorite, created_at) VALUES ('c0254c36-2d64-47e3-ad2b-0561ab9c5d74', 'Jago Mohan Pyare', '', '', '', 'jago-mohan-pyare', 'Favourite Song', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/songs/jago-mohan-pyare/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/songs/jago-mohan-pyare/gallery/c0254c36-2d64-47e3-ad2b-0561ab9c5d74-0.mp4"]', '', 'Hearing you listen to Jago Mohan Pyare in Raag Bhairav for the very first time was magical. You just stared at the music, your eyes wide with wonder, as if the notes were telling you a beautiful story only you could understand.

Our Nightly Ritual

Every night, after a long day, we sit together - you and dad. We play your favourite song, and you listen... sometimes quietly, sometimes with a little smile, sometime even humming along in your own way.

You love it so much that you ask for it again and again! You are so curious, so focused... always trying to understand every note, every rhythm.

Keep listening, keep feeling, keep growing... There''s a whole world of beautiful music waiting for you.!

This is not just a song anymore, it''s a part of our special time, our bond, and your beautiful journey with music.

♡', '[]', 0, 0, '2026-08-16T18:46:47.657599+00:00');
INSERT OR IGNORE INTO favorite_songs (id, title, artist, month, age, slug, category, cover_image, gallery_images, video_url, story, highlights, display_order, favorite, created_at) VALUES ('ac572ee4-86b0-4e38-8b33-699688b39725', 'Kombdi Padali', '', 'April 2025', '', 'kombdi-padali', 'Favourite Song', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/songs/kombdi-padali/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/songs/kombdi-padali/gallery/ac572ee4-86b0-4e38-8b33-699688b39725-0.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/songs/kombdi-padali/gallery/ac572ee4-86b0-4e38-8b33-699688b39725-1.mp4","https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/songs/kombdi-padali/gallery/ac572ee4-86b0-4e38-8b33-699688b39725-2.mp4"]', '', 'Today was one of those little moments that became a forever memory. ❤️

“Komdi Padali” was playing in the background—his favourite song. He loved the tune, he loved the rhythm, and this time, something was different.

For the very first time, he started reacting to the music. His eyes lit up, his face filled with excitement, and then came the sweetest surprise… he started dancing on his knees! 🎶🥰



It was such a simple moment, but one we’ll cherish forever. A favourite song, a little rhythm, and his very first dance—memories like these are what make childhood so beautiful.

From this day on, “Komdi Padali” will always be special to us… because it will forever be remembered as the song that made him dance for the very first time. ❤️🎵', '[]', 0, 0, '2026-08-16T05:44:14.100243+00:00');
INSERT OR IGNORE INTO favorite_songs (id, title, artist, month, age, slug, category, cover_image, gallery_images, video_url, story, highlights, display_order, favorite, created_at) VALUES ('1df681e4-7bc6-4842-a64b-344387fb063c', 'TEST', '', 'aug 2026', '', 'test', 'Favourite Song', 'https://fbfdwmlqoxfcqhodldpw.supabase.co/storage/v1/object/public/timeline/test/1787205765526-tsew36lz-ChatGPT-Image-Aug-20-2026-11_31_13-AM.webp', '["https://fbfdwmlqoxfcqhodldpw.supabase.co/storage/v1/object/public/timeline/test/gallery/1787205765936-dvek1d1i-ChatGPT-Image-Aug-20-2026-11_31_13-AM.webp"]', '', 'TEST', '[]', 0, 0, '2026-08-20T06:02:45.713039+00:00');
INSERT OR IGNORE INTO favorite_songs (id, title, artist, month, age, slug, category, cover_image, gallery_images, video_url, story, highlights, display_order, favorite, created_at) VALUES ('beae3c3d-d4ae-4ee1-b4ac-ffef893a955f', 'Jago Brij Raj Kuwar', '', 'Jan 2025', '', 'jago-brij-raj-kuwar', 'Favourite Song', 'https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/songs/jago-brij-raj-kuwar/cover.webp', '["https://azain-media-worker.aaawaizshaikh.workers.dev/media/media/songs/jago-brij-raj-kuwar/gallery/beae3c3d-d4ae-4ee1-b4ac-ffef893a955f-0.mp4"]', '', 'Your First Song — A Melody to Remember

Some memories begin with a photograph.

Others begin with a sound.

Your very first song was one of those moments we know we''ll remember for years to come.

It was Raag Bhairav, and Sohail Chachu was singing “Jago Brij Raj Kuwar” just for you.

You didn''t sing along.
You didn''t clap.
You didn''t even make much of a sound.

You simply stared at him.

Those big, curious eyes stayed fixed on him as though you were trying to understand every note, every word, every little movement.

And somehow, that made the moment even more beautiful.

For Sohail Chachu, it was a song.

For you, perhaps, it was your very first little introduction to the world of Indian classical music.

And for all of us watching, it was a memory worth holding on to — a tiny baby listening so seriously to a song sung especially for him.

We don''t know what you''ll remember from these early days.

But we will.

We''ll remember the room.
We''ll remember the song.
We''ll remember Chachu singing.
And most of all, we''ll remember you just staring at him with those beautiful eyes.

Maybe one day, you''ll hear “Jago Brij Raj Kuwar” again and we''ll tell you,

“This was your very first song.”

And we''ll show you this little moment when you were too young to understand music, but somehow already knew how to listen.

Your first raag.
Your first song.
Your first musical memory.

A tiny beginning to what we hope will be a lifetime filled with beautiful melodies. 🤍🎶', '[]', 0, 0, '2026-08-14T17:23:27.026747+00:00');

