INSERT OR IGNORE INTO letters (id, slot_key, title, slug, letter_content, date, age, signature, published, display_order, created_at, updated_at) VALUES ('1', 'daddy', 'A Letter For My Little Boy', 'a-letter-for-my-little-boy', 'Dear Azain,

I want you to always remember how deeply you are loved.

Every little moment with you is a memory that we will treasure forever.

As you grow, I hope you always know that your Papa will be cheering for you, believing in you, and loving you with all his heart.

Keep smiling, keep exploring, and always be your wonderful little self.

Love,
Papa ❤️', 'August 2026', 'Almost 2 Years', 'Love,
